CREATE ROLE fixture_backup LOGIN NOSUPERUSER NOBYPASSRLS NOCREATEROLE NOCREATEDB NOREPLICATION;
GRANT CONNECT ON DATABASE gateway TO fixture_backup;
GRANT USAGE ON SCHEMA public TO fixture_backup;
GRANT SELECT ON ALL TABLES IN SCHEMA public TO fixture_backup;
GRANT SELECT ON ALL SEQUENCES IN SCHEMA public TO fixture_backup;
GRANT EXECUTE ON FUNCTION pg_catalog.pg_control_system() TO fixture_backup;
ALTER DEFAULT PRIVILEGES FOR ROLE gateway GRANT USAGE ON SCHEMAS TO fixture_backup;
ALTER DEFAULT PRIVILEGES FOR ROLE gateway GRANT SELECT ON TABLES TO fixture_backup;
ALTER DEFAULT PRIVILEGES FOR ROLE gateway GRANT SELECT ON SEQUENCES TO fixture_backup;
